mapper.select:
select a.* from `all_process_instance` a
inner join `act_hi_taskinst` b on a.`proc_inst_id`=b.`PROC_INST_ID_`
where
`type` ='APPROVAL'
and `TENANT_ID_` = #{tenant}

    and b.`END_TIME_` >= #{param.submitTime.begin}
    and b.`END_TIME_` <= #{param.submitTime.end}


    and a.`business_model`=#{param.applicationCode}


    and a.`business_type`=#{param.businessType}

AND b.`TASK_DEF_KEY_` != 'root'
and b.`ASSIGNEE_`=#{param.startUserId}
GROUP BY b.`PROC_INST_ID_`
ORDER BY b.`END_TIME_` DESC
